class Solution {
    public int[] threeEqualParts(int[] arr) {
        int ones = 0;
        for (int b : arr) ones += b;
        if (ones == 0) return new int[]{0, 2};
        if (ones % 3 != 0) return new int[]{-1, -1};
        int k = ones / 3;
        int i1 = -1, i2 = -1, i3 = -1, count = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == 1) {
                count++;
                if (count == 1) i1 = i;
                if (count == k + 1) i2 = i;
                if (count == 2 * k + 1) i3 = i;
            }
        }
        while (i3 < arr.length) {
            if (arr[i1] != arr[i2] || arr[i1] != arr[i3]) return new int[]{-1, -1};
            i1++; i2++; i3++;
        }
        return new int[]{i1 - 1, i2};
    }
}

class Solution {
    public int[] threeEqualParts(int[] arr) {
        int n = arr.length;
        int ones = 0;
        for (int b : arr) ones += b;
        if (ones == 0) return new int[]{0, 2};
        if (ones % 3 != 0) return new int[]{-1, -1};
        int k = ones / 3;
        int[] starts = new int[3];
        int cnt = 0, si = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] == 1) {
                cnt++;
                if (cnt == 1) starts[0] = i;
                if (cnt == k + 1) starts[1] = i;
                if (cnt == 2 * k + 1) starts[2] = i;
            }
        }
        int trailingZeros = n - 1 - starts[2];
        for (int offset = 0; ; offset++) {
            int p1 = starts[0] + offset;
            int p2 = starts[1] + offset;
            int p3 = starts[2] + offset;
            if (p3 >= n) return new int[]{-1, -1};
            if (arr[p1] != arr[p2] || arr[p1] != arr[p3]) return new int[]{-1, -1};
            if (p3 == n - 1) {
                return new int[]{p1, p2 + 1};
            }
        }
    }
}
